use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use clap::{Command, Arg, ArgAction};
use regex::Regex;
use ignore::WalkBuilder;
use glob::Pattern;

#[derive(Debug, Clone)]
struct Config {
    disabled: Vec<String>,
    ignore: Vec<String>,
}

#[derive(Debug, Clone)]
struct Diagnostic {
    path: String,
    line: usize,
    col: usize,
    end_col: usize,
    severity: char, // 'W' or 'E'
    code: usize,
    message: String,
    title: String,
    lint_name: String,
    // For fix
    fix_range: Option<(usize, usize, String)>, // start byte offset, end byte offset, replacement
    // For stderr grouping, we may have multiple spans, but for simple we have one
}

#[derive(Debug, Clone)]
struct LintInfo {
    code: &'static str,
    name: &'static str,
    title: &'static str,
    explain: &'static str,
}

fn lint_infos() -> Vec<LintInfo> {
    vec![
        LintInfo { code: "W01", name: "bool_comparison", title: "Unnecessary comparison with boolean", explain: "## What it does\nChecks for expressions of the form `x == true`, `x != true` and\nsuggests using the variable directly.\n\n## Why is this bad?\nUnnecessary code.\n\n## Example\nInstead of checking the value of `x`:\n\n```nix\nif x == true then 0 else 1\n```\n\nUse `x` directly:\n\n```nix\nif x then 0 else 1\n```\n" },
        LintInfo { code: "W02", name: "empty_let_in", title: "Useless let-in expression", explain: "## What it does\nChecks for `let-in` expressions which create no new bindings.\n\n## Why is this bad?\n`let-in` expressions that create no new bindings are useless.\nThese are probably remnants from debugging or editing expressions.\n\n## Example\n\n```nix\nlet in pkgs.statix\n```\n\nPreserve only the body of the `let-in` expression:\n\n```nix\npkgs.statix\n```\n" },
        LintInfo { code: "W03", name: "manual_inherit", title: "Assignment instead of inherit", explain: "## What it does\nChecks for bindings of the form `a = a`.\n\n## Why is this bad?\nIf the aim is to bring attributes from a larger scope into\nthe current scope, prefer an inherit statement.\n\n## Example\n\n```nix\nlet\n  a = 2;\nin\n  { a = a; b = 3; }\n```\n\nTry `inherit` instead:\n\n```nix\nlet\n  a = 2;\nin\n  { inherit a; b = 3; }\n```\n" },
        LintInfo { code: "W04", name: "manual_inherit_from", title: "Assignment instead of inherit from", explain: "## What it does\nChecks for bindings of the form `a = someAttr.a`.\n\n## Why is this bad?\nIf the aim is to extract or bring attributes of an attrset into\nscope, prefer an inherit statement.\n\n## Example\n\n```nix\nlet\n  mtl = pkgs.haskellPackages.mtl;\nin\n  null\n```\n\nTry `inherit` instead:\n\n```nix\nlet\n  inherit (pkgs.haskellPackages) mtl;\nin\n  null\n```\n" },
        LintInfo { code: "W05", name: "legacy_let_syntax", title: "Using undocumented `let` syntax", explain: "## What it does\nChecks for legacy-let syntax that was never formalized.\n\n## Why is this bad?\nThis syntax construct is undocumented, refrain from using it.\n\n## Example\n\nLegacy let syntax makes use of an attribute set annotated with\n`let` and expects a `body` attribute.\n```nix\nlet {\n  body = x + y;\n  x = 2;\n  y = 3;\n}\n```\n\nThis is trivially representible via `rec`, which is documented\nand more widely known:\n\n```nix\nrec {\n  body = x + y;\n  x = 2;\n  y = 3;\n}.body\n```\n" },
        LintInfo { code: "W06", name: "collapsible_let_in", title: "These let-in expressions are collapsible", explain: "## What it does\nChecks for `let-in` expressions whose body is another `let-in`\nexpression.\n\n## Why is this bad?\nUnnecessary code, the `let-in` expressions can be merged.\n\n## Example\n\n```nix\nlet\n  a = 2;\nin\nlet\n  b = 3;\nin\n  a + b\n```\n\nMerge both `let-in` expressions:\n\n```nix\nlet\n  a = 2;\n  b = 3;\nin\n  a + b\n```\n" },
        LintInfo { code: "W07", name: "eta_reduction", title: "This function expression is eta reducible", explain: "## What it does\nChecks for eta-reducible functions, i.e.: converts lambda\nexpressions into free standing functions where applicable.\n\n## Why is this bad?\nOftentimes, eta-reduction results in code that is more natural\nto read.\n\n## Example\n\n```nix\nlet\n  double = i: 2 * i;\nin\nmap (x: double x) [ 1 2 3 ]\n```\n\nThe lambda passed to the `map` function is eta-reducible, and the\nresult reads more naturally:\n\n```nix\nlet\n  double = i: 2 * i;\nin\nmap double [ 1 2 3 ]\n```\n" },
        LintInfo { code: "W08", name: "useless_parens", title: "These parentheses can be omitted", explain: "## What it does\nChecks for unnecessary parentheses.\n\n## Why is this bad?\nUnnecessarily parenthesized code is hard to read.\n\n## Example\n\n```nix\nlet\n  double = (x: 2 * x);\n  ls = map (double) [ 1 2 3 ];\nin\n  (2 + 3)\n```\n\nRemove unnecessary parentheses:\n\n```nix\nlet\n  double = x: 2 * x;\n  ls = map double [ 1 2 3 ];\nin\n  2 + 3\n```\n" },
        LintInfo { code: "W10", name: "empty_pattern", title: "Found empty pattern in function argument", explain: "## What it does\nChecks for an empty variadic pattern: `{...}`, in a function\nargument.\n\n## Why is this bad?\nThe intention with empty patterns is not instantly obvious. Prefer\nan underscore identifier instead, to indicate that the argument\nis being ignored.\n\n## Example\n\n```nix\nclient = { ... }: {\n  services.irmaseal-pkg.enable = true;\n};\n```\n\nReplace the empty variadic pattern with `_` to indicate that you\nintend to ignore the argument:\n\n```nix\nclient = _: {\n  services.irmaseal-pkg.enable = true;\n};\n```\n" },
        LintInfo { code: "W11", name: "redundant_pattern_bind", title: "Found redundant pattern bind in function argument", explain: "## What it does\nChecks for binds of the form `inputs @ { ... }` in function\narguments.\n\n## Why is this bad?\nThe variadic pattern here is redundant, as it does not capture\nanything.\n\n## Example\n\n```nix\ninputs @ { ... }: inputs.nixpkgs\n```\n\nRemove the pattern altogether:\n\n```nix\ninputs: inputs.nixpkgs\n```\n" },
        LintInfo { code: "W12", name: "unquoted_uri", title: "Found unquoted URI expression", explain: "## What it does\nChecks for URI expressions that are not quoted.\n\n## Why is this bad?\nThe Nix language has a special syntax for URLs even though quoted\nstrings can also be used to represent them. Unlike paths, URLs do\nnot have any special properties in the Nix expression language\nthat would make the difference useful. Moreover, using variable\nexpansion in URLs requires some URLs to be quoted strings anyway.\nSo the most consistent approach is to always use quoted strings to\nrepresent URLs. Additionally, a semicolon immediately after the\nURL can be mistaken for a part of URL by language-agnostic tools\nsuch as terminal emulators.\n\nSee RFC 00045 [1] for more.\n\n[1]: https://github.com/NixOS/rfcs/blob/master/rfcs/0045-deprecate-url-syntax.md\n\n## Example\n\n```nix\ninputs = {\n  gitignore.url = github:hercules-ci/gitignore.nix;\n}\n```\n\nQuote the URI expression:\n\n```nix\ninputs = {\n  gitignore.url = \"github:hercules-ci/gitignore.nix\";\n}\n```\n" },
        LintInfo { code: "W14", name: "empty_inherit", title: "Found empty inherit statement", explain: "## What it does\nChecks for empty inherit statements.\n\n## Why is this bad?\nUseless code, probably the result of a refactor.\n\n## Example\n\n```nix\ninherit;\n```\n\nRemove it altogether.\n" },
        LintInfo { code: "W17", name: "deprecated_to_path", title: "Found usage of deprecated builtin toPath", explain: "## What it does\nChecks for usage of the `toPath` function.\n\n## Why is this bad?\n`toPath` is deprecated.\n\n## Example\n\n```nix\nbuiltins.toPath \"/path\"\n```\n\nTry these instead:\n\n```nix\n# to convert the string to an absolute path:\n/. + \"/path\"\n# => /abc\n\n# to convert the string to a path relative to the current directory:\n./. + \"/bin\"\n# => /home/np/statix/bin\n```\n" },
        LintInfo { code: "W18", name: "bool_simplification", title: "This boolean expression can be simplified", explain: "## What it does\nChecks for boolean expressions that can be simplified.\n\n## Why is this bad?\nComplex booleans affect readibility.\n\n## Example\n```nix\nif !(x == y) then 0 else 1\n```\n\nUse `!=` instead:\n\n```nix\nif x != y then 0 else 1\n```\n" },
        LintInfo { code: "W19", name: "useless_has_attr", title: "This `if` expression can be simplified with `or`", explain: "## What it does\nChecks for expressions that use the \"has attribute\" operator: `?`,\nwhere the `or` operator would suffice.\n\n## Why is this bad?\nThe `or` operator is more readable.\n\n## Example\n```nix\nif x ? a then x.a else some_default\n```\n\nUse `or` instead:\n\n```nix\nx.a or some_default\n```\n" },
        LintInfo { code: "W20", name: "repeated_keys", title: "Avoid repeated keys in attribute sets", explain: "## What it does\nChecks for keys in attribute sets with repetitive keys, and suggests using\nan attribute set instead.\n\n## Why is this bad?\nAvoiding repetetion helps improve readibility.\n\n## Example\n```nix\n{\n  foo.a = 1;\n  foo.b = 2;\n  foo.c = 3;\n}\n```\n\nDon't repeat.\n```nix\n{\n  foo = {\n    a = 1;\n    b = 2;\n    c = 3;\n  };\n}\n```\n" },
        LintInfo { code: "W23", name: "empty_list_concat", title: "Unnecessary concatenation with empty list", explain: "## What it does\nChecks for concatenations to empty lists\n\n## Why is this bad?\nConcatenation with the empty list is a no-op.\n\n## Example\n```nix\n[] ++ something\n```\n\nRemove the operation:\n\n```nix\nsomething\n```\n" },
    ]
}

fn code_to_num(code: &str) -> usize {
    if code.starts_with('W') {
        code[1..].parse::<usize>().unwrap_or(0)
    } else {
        0
    }
}

fn load_config(conf_path: &str) -> Result<Config, String> {
    let p = Path::new(conf_path);
    let config_file: PathBuf;
    if p.is_file() {
        config_file = p.to_path_buf();
    } else if p.is_dir() {
        let candidate = p.join("statix.toml");
        if candidate.is_file() {
            config_file = candidate;
        } else {
            // no config file, treat as empty
            return Ok(Config { disabled: vec![], ignore: vec![] });
        }
    } else {
        // check if path's parent contains statix.toml? spec says path to file or its parent dir
        // Actually if conf_path is file path that doesn't exist, error
        // If it's dir that doesn't exist, error
        return Err(format!("config error: path error: No such file or directory (os error 2)"));
    }

    // read file
    let content = match fs::read_to_string(&config_file) {
        Ok(c) => c,
        Err(_) => return Err(format!("config error: path error: No such file or directory (os error 2)")),
    };

    // parse toml using toml crate 0.5? We have 0.5 available? We have 1.1.2 but we use 0.5 in Cargo? We set toml = "0.5"
    // Try to parse with toml crate
    // For simplicity, use toml crate 0.5 API: toml::from_str
    #[derive(serde::Deserialize)]
    struct RawConfig {
        disabled: Option<Vec<String>>,
        ignore: Option<Vec<String>>,
    }

    match toml::from_str::<RawConfig>(&content) {
        Ok(rc) => {
            Ok(Config {
                disabled: rc.disabled.unwrap_or_default(),
                ignore: rc.ignore.unwrap_or_default(),
            })
        },
        Err(e) => {
            Err(format!("config error: unable to parse config file: {}", e))
        }
    }
}

// helper to compute line/col from byte offset
fn offset_to_line_col(content: &str, offset: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, ch) in content.char_indices() {
        if i >= offset {
            break;
        }
        if ch == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

fn line_content(content: &str, line_no: usize) -> String {
    content.lines().nth(line_no - 1).unwrap_or("").to_string()
}

// lint functions
fn lint_file(path: &str, content: &str, disabled: &HashSet<String>) -> Vec<Diagnostic> {
    let mut diags = Vec::new();

    // Helper to check disabled
    let is_disabled = |name: &str| -> bool {
        disabled.contains(name)
    };

    // Very basic syntax check: if content empty -> E00
    if content.trim().is_empty() {
        // produce parse error like original: Unexpected end of file at 1:1
        // original for empty file: "/tmp/empty.nix>1:1:E:0:Unexpected end of file"
        diags.push(Diagnostic {
            path: path.to_string(),
            line: 1,
            col: 1,
            end_col: 2,
            severity: 'E',
            code: 0,
            message: "Unexpected end of file".to_string(),
            title: "Syntax error".to_string(),
            lint_name: "".to_string(),
            fix_range: None,
        });
        return diags;
    }

    // W01 bool_comparison
    if !is_disabled("bool_comparison") {
        // regex for comparison
        let re = Regex::new(r"(?P<left>\b\w+\b|\btrue\b|\bfalse\b)\s*(?P<op>==|!=)\s*(?P<right>\b\w+\b|\btrue\b|\bfalse\b)").unwrap();
        for mat in re.find_iter(content) {
            let mstr = mat.as_str();
            // check if one side is true/false and other is not true/false? Actually both can be true/false? but we care if one is bool literal
            // parse left, op, right via capture? Use same regex with groups but we used find_iter not captures; let's use captures_iter
        }
        let re_cap = Regex::new(r"(?P<left>\b\w+\b)\s*(?P<op>==|!=)\s*(?P<right>true|false)\b|(?P<right2>true|false)\s*(?P<op2>==|!=)\s*(?P<left2>\b\w+\b)").unwrap();
        // Actually we need to iterate captures
        for caps in re_cap.captures_iter(content) {
            // Determine which alternative matched
            let (var, op, bool_lit) = if caps.name("left").is_some() {
                let left = caps.name("left").unwrap().as_str();
                let op = caps.name("op").unwrap().as_str();
                let right = caps.name("right").unwrap().as_str();
                (left, op, right)
            } else {
                let left = caps.name("left2").unwrap().as_str();
                let op = caps.name("op2").unwrap().as_str();
                let right = caps.name("right2").unwrap().as_str();
                (left, op, right)
            };
            // var should not be true/false
            if var == "true" || var == "false" {
                continue;
            }
            // check if var is keyword? ignore
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            let message = format!("Comparing `{}` with boolean literal `{}`", var, bool_lit);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 1,
                message,
                title: "Unnecessary comparison with boolean".to_string(),
                lint_name: "bool_comparison".to_string(),
                fix_range: Some((start, end, {
                    // compute fix
                    if (op == "==" && bool_lit == "true") || (op == "!=" && bool_lit == "false") {
                        var.to_string()
                    } else {
                        format!("!{}", var)
                    }
                })),
            });
        }
    }

    // W02 empty_let_in
    if !is_disabled("empty_let_in") {
        let re = Regex::new(r"\blet\s+in\b").unwrap();
        for mat in re.find_iter(content) {
            let start = mat.start();
            let end = mat.end();
            // need to find body after "in"
            let after = &content[end..];
            // Find next non-whitespace token up to newline? For fix, we need to extract body
            // Simplistic: body is rest of file after "in" trimmed? Actually "let in pkgs.statix" body is "pkgs.statix"
            // We'll approximate: find first non-whitespace after "in", then take up to end of line or file?
            // For our diagnostic, we need line/col
            let (line, col) = offset_to_line_col(content, start);
            // For fix range, we want to replace "let in" plus following whitespace with ""
            // Actually original fix: "let in pkgs.statix" => "pkgs.statix" (removes "let in " including trailing space)
            // So fix range from start to start of body
            // Find body start: skip whitespace after "in"
            let mut body_start = end;
            let bytes = content.as_bytes();
            while body_start < content.len() && (bytes[body_start] == b' ' || bytes[body_start] == b'\t' || bytes[body_start] == b'\n' || bytes[body_start] == b'\r') {
                body_start += 1;
            }
            // body end is up to end of content? For simplicity, we replace "let\s+in\s+" with ""
            let fix = if body_start <= content.len() {
                // replacement is "": we will delete up to body_start, keeping body
                // So fix range is start..body_start, replacement ""
                // But we need to keep body, so actually we want to delete only "let in" part
                // Let's do that
                Some((start, body_start, "".to_string()))
            } else {
                None
            };
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 2,
                message: "This let-in expression has no entries".to_string(),
                title: "Useless let-in expression".to_string(),
                lint_name: "empty_let_in".to_string(),
                fix_range: fix,
            });
        }
    }

    // W03 manual_inherit
    if !is_disabled("manual_inherit") {
        // pattern: (\b\w+\b)\s*=\s*\1\s*;
        let re = Regex::new(r"(?P<ident>\b\w+\b)\s*=\s*(?P=ident)\s*;").unwrap();
        for caps in re.captures_iter(content) {
            let mat = caps.get(0).unwrap();
            let ident = caps.name("ident").unwrap().as_str();
            // avoid if inside inherit? The pattern "inherit a;" would not match because no "="
            // Also avoid if left side is part of "inherit"? but we already only match "="
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 3,
                message: "This assignment is better written with `inherit`".to_string(),
                title: "Assignment instead of inherit".to_string(),
                lint_name: "manual_inherit".to_string(),
                fix_range: Some((start, end, format!("inherit {};", ident))),
            });
        }
    }

    // W04 manual_inherit_from
    if !is_disabled("manual_inherit_from") {
        // pattern: (\w+)\s*=\s*([\w\.]+)\s*; where last component of path == ident
        let re = Regex::new(r"(?P<left>\b\w+\b)\s*=\s*(?P<right>[A-Za-z0-9_\.]+)\s*;").unwrap();
        for caps in re.captures_iter(content) {
            let left = caps.name("left").unwrap().as_str();
            let right = caps.name("right").unwrap().as_str();
            // Skip if left == right (that's W03, not W04)
            if left == right {
                continue;
            }
            // Check if right ends with ".left"
            if right.contains('.') {
                if let Some(last) = right.split('.').last() {
                    if last == left {
                        // This is W04
                        // Also need to ensure not already handled by W03 (we already skip exact equal)
                        let mat = caps.get(0).unwrap();
                        let start = mat.start();
                        let end = mat.end();
                        let (line, col) = offset_to_line_col(content, start);
                        // prefix is right without last component
                        let prefix = &right[..right.rfind('.').unwrap()];
                        diags.push(Diagnostic {
                            path: path.to_string(),
                            line,
                            col,
                            end_col: col + (end - start),
                            severity: 'W',
                            code: 4,
                            message: "This assignment is better written with `inherit`".to_string(),
                            title: "Assignment instead of inherit from".to_string(),
                            lint_name: "manual_inherit_from".to_string(),
                            fix_range: Some((start, end, format!("inherit ({}) {};", prefix, left))),
                        });
                    }
                }
            }
        }
    }

    // W05 legacy_let_syntax
    if !is_disabled("legacy_let_syntax") {
        let re = Regex::new(r"\blet\s*\{").unwrap();
        for mat in re.find_iter(content) {
            // Check if inside contains "body ="
            let start = mat.start();
            // Find closing } - simplistic: find next } after start, but may be nested? We'll just check if content from start contains "body"
            let slice = &content[start..];
            if slice.contains("body") {
                // Find matching }? Simplistic: find first "}" after
                if let Some(end_brace) = slice.find('}') {
                    let end = start + end_brace + 1; // include }
                    let (line, col) = offset_to_line_col(content, start);
                    // For fix, we need to transform let { ... } to rec { ... }.body
                    // Get inner content between { and }
                    let inner = &slice[5..end_brace]; // after "let {"
                    // Actually "let {" is 4 chars? "let" + whitespace + "{" = maybe 5? We'll just extract between first { and matching }
                    // Simplified fix: replace "let {" with "rec {" and append ".body" after "}"
                    let fix_str = format!("rec {{{{}}}.body", inner); // placeholder
                    // For now produce fix that will be handled specially in fix logic
                    diags.push(Diagnostic {
                        path: path.to_string(),
                        line,
                        col,
                        end_col: col + 4,
                        severity: 'W',
                        code: 5,
                        message: "Prefer `rec` over undocumented `let` syntax".to_string(),
                        title: "Using undocumented `let` syntax".to_string(),
                        lint_name: "legacy_let_syntax".to_string(),
                        fix_range: Some((start, end, format!("rec {{{}}}.body", inner))),
                    });
                }
            }
        }
    }

    // W06 collapsible_let_in - detect "let ... in let"
    if !is_disabled("collapsible_let_in") {
        // This is a bit more complex, need to find let ... in let ... in
        let re = Regex::new(r"let\s+(?P<outer>[^;]*?;.*?)\s*in\s+let\s+(?P<inner>[^;]*?;.*?)\s*in").unwrap();
        // Actually for simple case "let a = 2; in let b = 3; in a + b"
        // We'll search for pattern "let ... in let"
        let re_simple = Regex::new(r"let\s+(?P<outer_bind>[^;]+;)\s*in\s+let\s+(?P<inner_bind>[^;]+;)\s*in").unwrap();
        for caps in re_simple.captures_iter(content) {
            let outer_bind = caps.name("outer_bind").unwrap().as_str();
            let inner_bind = caps.name("inner_bind").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            // Find inner let start position
            let inner_start = content[mat.start()..].find("let").unwrap() + mat.start();
            let inner_let_pos = content[inner_start..].find("let").unwrap() + inner_start;
            // Actually second let is after "in "
            // For diagnostic, we need two diagnostics grouped? For now produce two separate but with same title? Original groups.
            // We'll produce one diagnostic for outer and one for inner, but we'll handle grouping later in stderr.
            // For fix, replace whole "let outer in let inner in" with "let outer  inner in"
            let replacement = format!("let {}  {} in", outer_bind, inner_bind);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + 3, // "let"
                severity: 'W',
                code: 6,
                message: "This `let in` expression contains a nested `let in` expression".to_string(),
                title: "These let-in expressions are collapsible".to_string(),
                lint_name: "collapsible_let_in".to_string(),
                fix_range: Some((start, end, replacement)),
            });
            // Also inner diagnostic
            // Find inner let position
            let inner_mat_start = content[start..].find("let").unwrap() + start; // outer let
            // second let
            let second_let_offset = content[inner_mat_start+3..].find("let").unwrap() + inner_mat_start + 3;
            let (line2, col2) = offset_to_line_col(content, second_let_offset);
            diags.push(Diagnostic {
                path: path.to_string(),
                line: line2,
                col: col2,
                end_col: col2 + 3,
                severity: 'W',
                code: 6,
                message: "This `let in` expression is nested".to_string(),
                title: "These let-in expressions are collapsible".to_string(),
                lint_name: "collapsible_let_in".to_string(),
                fix_range: None, // inner fix not needed separately, outer fix covers
            });
        }
    }

    // W07 eta_reduction
    if !is_disabled("eta_reduction") {
        let re = Regex::new(r"\(\s*(?P<param>\w+)\s*:\s*(?P<func>\w+)\s+(?P=param)\s*\)").unwrap();
        for caps in re.captures_iter(content) {
            let param = caps.name("param").unwrap().as_str();
            let func = caps.name("func").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 7,
                message: format!("Found eta-reduction: `{}`", func),
                title: "This function expression is eta reducible".to_string(),
                lint_name: "eta_reduction".to_string(),
                fix_range: Some((start, end, func.to_string())),
            });
        }
    }

    // W08 useless_parens - detect "(ident)" or "(ident.ident)" or "(lambda)"
    if !is_disabled("useless_parens") {
        // For value in binding: let a = (2);  or let a = (x: 2 * x);
        let re_binding = Regex::new(r"=\s*\(\s*(?P<inner>[^()\n]+?)\s*\)\s*;").unwrap();
        for caps in re_binding.captures_iter(content) {
            let inner = caps.name("inner").unwrap().as_str();
            // If inner is simple (not containing "++" or "+"? but we want to flag "(2)" and "(x: 2 * x)")
            // For our purposes, flag if inner doesn't contain parentheses and is not binary op with + etc? But let's just flag all "(...)" after "="
            // Avoid if inner is empty
            if inner.trim().is_empty() {
                continue;
            }
            // Check if original had "(2 + 3)" which should NOT be flagged per earlier test? Actually "(2 + 3)" gave no warning, so we should not flag if inner contains "+"?
            // Our earlier test: "(2 + 3)" gave no warning, but "(a)" did, "(a.b)" did, "([1 2 3])"? Need to test
            // For now, flag if inner is single token or lambda
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            // Find inner start inside parens
            let inner_start = content[start..].find('(').unwrap() + start + 1;
            let (line, col) = offset_to_line_col(content, inner_start -1); // col of '('
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 8,
                message: "Useless parentheses around value in binding".to_string(),
                title: "These parentheses can be omitted".to_string(),
                lint_name: "useless_parens".to_string(),
                fix_range: Some((start, end, format!("= {};", inner))),
            });
        }
        // Also parens around primitive: "(a)" standalone?
        let re_prim = Regex::new(r"\(\s*(?P<inner>\w+(\.\w+)*)\s*\)").unwrap();
        for caps in re_prim.captures_iter(content) {
            let inner = caps.name("inner").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            // Avoid if already part of binding case? We'll still produce but may duplicate
            // Check if preceded by "=" already handled? Skip if preceded by "="?
            let start = mat.start();
            // If char before is "=" with maybe spaces, we already handled
            let before = &content[..start].trim_end();
            if before.ends_with('=') {
                continue;
            }
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (mat.end() - mat.start()),
                severity: 'W',
                code: 8,
                message: "Useless parentheses around primitive expression".to_string(),
                title: "These parentheses can be omitted".to_string(),
                lint_name: "useless_parens".to_string(),
                fix_range: Some((start, mat.end(), inner.to_string())),
            });
        }
    }

    // W10 empty_pattern
    if !is_disabled("empty_pattern") {
        let re = Regex::new(r"\{\s*\.\.\.\s*\}").unwrap();
        for mat in re.find_iter(content) {
            // Check if followed by ":" (function pattern)
            let end = mat.end();
            let after = &content[end..];
            let after_trim = after.trim_start();
            if after_trim.starts_with(':') {
                let start = mat.start();
                let (line, col) = offset_to_line_col(content, start);
                diags.push(Diagnostic {
                    path: path.to_string(),
                    line,
                    col,
                    end_col: col + (mat.end() - mat.start()),
                    severity: 'W',
                    code: 10,
                    message: "This pattern is empty, use `_` instead".to_string(),
                    title: "Found empty pattern in function argument".to_string(),
                    lint_name: "empty_pattern".to_string(),
                    fix_range: Some((start, end, "_".to_string())),
                });
            }
        }
    }

    // W11 redundant_pattern_bind
    if !is_disabled("redundant_pattern_bind") {
        let re = Regex::new(r"(?P<ident>\b\w+\b)\s*@\s*\{\s*\.\.\.\s*\}\s*:").unwrap();
        for caps in re.captures_iter(content) {
            let ident = caps.name("ident").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 11,
                message: format!("This pattern bind is redundant, use `{}` instead", ident),
                title: "Found redundant pattern bind in function argument".to_string(),
                lint_name: "redundant_pattern_bind".to_string(),
                fix_range: Some((start, end, format!("{}:", ident))),
            });
        }
    }

    // W12 unquoted_uri
    if !is_disabled("unquoted_uri") {
        // simplistic: detect " = <scheme>:<path>;" where scheme is like github, https, etc and not quoted
        let re = Regex::new(r"=\s*(?P<uri>[a-zA-Z][a-zA-Z0-9+.-]*:[^\s;\"'{}]+)\s*;").unwrap();
        for caps in re.captures_iter(content) {
            let uri = caps.name("uri").unwrap().as_str();
            // Skip if uri is inside quotes (our regex already excludes quotes)
            // Also check if uri contains "://"
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let uri_start = caps.name("uri").unwrap().start();
            let uri_end = caps.name("uri").unwrap().end();
            let (line, col) = offset_to_line_col(content, uri_start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (uri_end - uri_start),
                severity: 'W',
                code: 12,
                message: "Consider quoting this URI expression".to_string(),
                title: "Found unquoted URI expression".to_string(),
                lint_name: "unquoted_uri".to_string(),
                fix_range: Some((uri_start, uri_end, format!("\"{}\"", uri))),
            });
        }
    }

    // W14 empty_inherit
    if !is_disabled("empty_inherit") {
        let re = Regex::new(r"inherit\s*;").unwrap();
        for mat in re.find_iter(content) {
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 14,
                message: "Remove this empty `inherit` statement".to_string(),
                title: "Found empty inherit statement".to_string(),
                lint_name: "empty_inherit".to_string(),
                fix_range: Some((start, end, "".to_string())),
            });
        }
        // also "inherit (a);"
        let re2 = Regex::new(r"inherit\s*\([^)]*\)\s*;").unwrap();
        for mat in re2.find_iter(content) {
            let txt = mat.as_str();
            // check if inside parens and after has no idents: e.g., "inherit (a);"
            // For our purposes, "inherit (a);" is empty inherit (no idents outside parens)
            // In example, "{ inherit (a); }" should be flagged? We saw it had no warning? Actually earlier we tested "{ inherit (a); }" and got no warning. So maybe "inherit (a);" is not considered empty? Wait W14 is empty inherit: "inherit;" alone, not "inherit (a);". But we had test for "inherit (a) b;" which is not empty.
            // The test "{ inherit (a); }" gave no warning, so "inherit (a);" is NOT empty? But spec says empty inherit is "inherit;" with no identifiers, but "inherit (a);" has parentheses but no identifiers outside, maybe still empty? Let's check original: for "{ inherit (a); }" we got no warning (see earlier). So "inherit (a);" is not considered empty? That seems odd.
            // Let's skip this second pattern for now.
        }
    }

    // W17 deprecated_to_path
    if !is_disabled("deprecated_to_path") {
        let re = Regex::new(r"builtins\.toPath").unwrap();
        for mat in re.find_iter(content) {
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 17,
                message: "`builtins.toPath` is deprecated, see `:doc builtins.toPath` within the REPL for more".to_string(),
                title: "Found usage of deprecated builtin toPath".to_string(),
                lint_name: "deprecated_to_path".to_string(),
                fix_range: None,
            });
        }
    }

    // W18 bool_simplification
    if !is_disabled("bool_simplification") {
        let re = Regex::new(r"!\s*\(\s*(?P<left>\w+)\s*==\s*(?P<right>\w+)\s*\)").unwrap();
        for caps in re.captures_iter(content) {
            let left = caps.name("left").unwrap().as_str();
            let right = caps.name("right").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 18,
                message: "Try `!=` instead of `!(... == ...)`".to_string(),
                title: "This boolean expression can be simplified".to_string(),
                lint_name: "bool_simplification".to_string(),
                fix_range: Some((start, end, format!("{} != {}", left, right))),
            });
        }
    }

    // W19 useless_has_attr
    if !is_disabled("useless_has_attr") {
        let re = Regex::new(r"if\s+(?P<obj>\w+)\s*\?\s*(?P<attr>[\w\.]+)\s+then\s+(?P=obj)\.(?P=attr)\s+else\s+(?P<default>[^\s;{}]+)").unwrap();
        for caps in re.captures_iter(content) {
            let obj = caps.name("obj").unwrap().as_str();
            let attr = caps.name("attr").unwrap().as_str();
            let default = caps.name("default").unwrap().as_str();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let end = mat.end();
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 19,
                message: format!("Consider using `{}.{} or {}` instead of this `if` expression", obj, attr, default),
                title: "This `if` expression can be simplified with `or`".to_string(),
                lint_name: "useless_has_attr".to_string(),
                fix_range: Some((start, end, format!("{}.{} or {}", obj, attr, default))),
            });
        }
    }

    // W20 repeated_keys
    if !is_disabled("repeated_keys") {
        // Find attrset with dotted keys sharing prefix
        // Simple: find all occurrences of "prefix.suffix ="
        let re = Regex::new(r"(?P<prefix>\b\w+\b)\.(?P<suffix>\w+)\s*=").unwrap();
        let mut map: HashMap<String, Vec<(usize, usize, String)>> = HashMap::new(); // prefix -> list of (offset, line, suffix)
        for caps in re.captures_iter(content) {
            let prefix = caps.name("prefix").unwrap().as_str().to_string();
            let mat = caps.get(0).unwrap();
            let start = mat.start();
            let (line, _) = offset_to_line_col(content, start);
            map.entry(prefix.clone()).or_default().push((start, line, caps.name("suffix").unwrap().as_str().to_string()));
        }
        for (prefix, occ) in map {
            if occ.len() >= 3 {
                // produce diagnostics for each occurrence
                // For simplicity, produce 3 diagnostics with messages as original
                // We'll create diagnostics for each occ
                for (idx, (offset, line_no, _suffix)) in occ.iter().enumerate() {
                    let (line, col) = offset_to_line_col(content, *offset);
                    let message = if idx == 0 {
                        format!("The key `{}` is first assigned here ...", prefix)
                    } else if idx == occ.len() - 1 {
                        let suffixes: Vec<String> = occ.iter().map(|(_, _, s)| format!("{}=...", s)).collect();
                        format!("... and here. Try `{} = {{ {} }}` instead.", prefix, suffixes.join("; "))
                    } else {
                        "... repeated here ...".to_string()
                    };
                    diags.push(Diagnostic {
                        path: path.to_string(),
                        line,
                        col,
                        end_col: col + prefix.len(),
                        severity: 'W',
                        code: 20,
                        message,
                        title: "Avoid repeated keys in attribute sets".to_string(),
                        lint_name: "repeated_keys".to_string(),
                        fix_range: None,
                    });
                }
            }
        }
    }

    // W23 empty_list_concat
    if !is_disabled("empty_list_concat") {
        // [] ++ x  and x ++ []
        let re1 = Regex::new(r"\[\]\s*\+\+\s*(?P<rest>[^\s;]+)").unwrap();
        for caps in re1.captures_iter(content) {
            let full = caps.get(0).unwrap();
            let start = full.start();
            let end = full.end();
            let rest = caps.name("rest").unwrap().as_str();
            // Avoid case "[] ++ []" which would be "[]"
            let (line, col) = offset_to_line_col(content, start);
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + 2,
                severity: 'W',
                code: 23,
                message: "Concatenation with the empty list, `[]`, is a no-op".to_string(),
                title: "Unnecessary concatenation with empty list".to_string(),
                lint_name: "empty_list_concat".to_string(),
                fix_range: Some((start, end, rest.to_string())),
            });
        }
        let re2 = Regex::new(r"(?P<left>[^\s\[\]]+)\s*\+\+\s*\[\]").unwrap();
        for caps in re2.captures_iter(content) {
            let left = caps.name("left").unwrap().as_str();
            let full = caps.get(0).unwrap();
            let start = full.start();
            let end = full.end();
            let (line, col) = offset_to_line_col(content, start);
            // Ensure left is not "[]"
            if left.trim() == "[]" {
                continue;
            }
            diags.push(Diagnostic {
                path: path.to_string(),
                line,
                col,
                end_col: col + (end - start),
                severity: 'W',
                code: 23,
                message: "Concatenation with the empty list, `[]`, is a no-op".to_string(),
                title: "Unnecessary concatenation with empty list".to_string(),
                lint_name: "empty_list_concat".to_string(),
                fix_range: Some((start, end, left.to_string())),
            });
        }
    }

    diags
}

fn format_errfmt(diags: &[Diagnostic]) -> String {
    let mut out = String::new();
    for d in diags {
        // format: <path>><line>:<col>:<severity>:<code>:<message>
        // For E, severity E, code 0
        // For W, severity W, code numeric
        out.push_str(&format!("{}>{}:{}:{}:{}:{}\n", d.path, d.line, d.col, d.severity, d.code, d.message));
    }
    out
}

fn format_stderr(diags: &[Diagnostic], contents: &HashMap<String, String>) -> String {
    // Group diagnostics by title and maybe by file? For simplicity, each diagnostic separate report except W06 and W20 which we group.
    // We'll implement simple grouping: if multiple diags have same lint_name and same title and same file (for W20) or same title (for W06), group them into one report with multiple spans.

    // For now, just produce one report per diagnostic (except we handle W20 grouping separately inside lint_file already produces multiple diags that should be grouped into one report)
    // Let's detect W20 and W06 grouping.

    let mut out = String::new();

    // Group by (path, lint_name) for W20 and W06?
    // We'll create map from (path, lint_name, title) -> Vec<Diagnostic>
    let mut groups: HashMap<(String, String, String), Vec<Diagnostic>> = HashMap::new();
    for d in diags {
        if d.lint_name == "repeated_keys" || d.lint_name == "collapsible_let_in" {
            let key = (d.path.clone(), d.lint_name.clone(), d.title.clone());
            groups.entry(key).or_default().push(d.clone());
        } else {
            // each单独
            let key = (d.path.clone(), d.lint_name.clone() + &format!("-{}-{}", d.line, d.col), d.title.clone());
            groups.entry(key).or_default().push(d.clone());
        }
    }

    for ((path, _lint_name, _title), group) in groups {
        // For each group, produce report
        if group.is_empty() {
            continue;
        }
        let first = &group[0];
        // Header
        if first.severity == 'W' {
            // Determine code string like W03
            let code_str = format!("W{:02}", first.code);
            out.push_str(&format!("\x1b[33m[{}] Warning:\x1b[0m {}\n", code_str, first.title));
        } else {
            out.push_str(&format!("\x1b[31m[E00] Error:\x1b[0m {}\n", first.title));
        }

        // For each diagnostic in group, print span
        for diag in &group {
            // file header
            out.push_str(&format!("   \x1b[38;5;246m╭\x1b[0m\x1b[38;5;246m─\x1b[0m\x1b[38;5;246m[\x1b[0m{}:{}:{}\x1b[38;5;246m]\x1b[0m\n", diag.path, diag.line, diag.col));
            out.push_str(&format!("   \x1b[38;5;246m│\x1b[0m\n"));
            // Get line content
            let file_content = contents.get(&diag.path).map(|s| s.as_str()).unwrap_or("");
            let line_str = line_content(file_content, diag.line);
            // Build colored line: each char colored
            let mut colored_line = String::new();
            for (idx, ch) in line_str.chars().enumerate() {
                let col = idx + 1;
                if col >= diag.col && col <= diag.end_col {
                    colored_line.push_str(&format!("\x1b[35m{}\x1b[0m", ch));
                } else {
                    colored_line.push_str(&format!("\x1b[38;5;249m{}\x1b[0m", ch));
                }
            }
            out.push_str(&format!(" \x1b[38;5;246m{} │\x1b[0m {}\n", diag.line, colored_line));

            // underline: spaces = col (per earlier observation, spaces = col)
            // But need to account for line number prefix? For simplicity, spaces = diag.col
            // Actually we need spaces equal to diag.col plus maybe? Let's use diag.col
            let mut underline = String::new();
            for _ in 0..diag.col {
                underline.push(' ');
            }
            // Build underline pattern: dashes with center ┬
            let len = if diag.end_col > diag.col { diag.end_col - diag.col } else { 1 };
            // For len, produce "─" * len with "┬" in middle
            let mut dash_str = String::new();
            for i in 0..len {
                if i == len / 2 {
                    dash_str.push('┬');
                } else {
                    dash_str.push('─');
                }
            }
            // Color the dash_str with magenta per char
            let mut colored_dash = String::new();
            for ch in dash_str.chars() {
                colored_dash.push_str(&format!("\x1b[35m{}\x1b[0m", ch));
            }
            out.push_str(&format!(" \x1b[38;5;246m  ·\x1b[0m{}{}\n", " ".repeat(diag.col), colored_dash));

            // Message line
            // For message, need to highlight parts with \x1b[36m
            // For simplicity, we will not color inner parts, just plain message, but original colors parts like `inherit` etc.
            // We'll try to color backticks content with cyan? In messages like "This assignment is better written with `inherit`", the word inherit inside backticks is cyan?
            // Original message line: "                    ╰──── This assignment is better written with \x1b[36minherit\x1b[0m"
            // So it does color inside message.
            // For simplicity, we will produce message with cyan for words inside backticks or inside `` ?
            // We'll implement simple: replace `xxx` with \x1b[36mxxx\x1b[0m ?
            // Also the "╰──── " part is magenta

            let mut msg = diag.message.clone();
            // Color backtick contents with cyan: very simplistic
            // We'll replace occurrences of "inherit" with cyan? Might be overkill.
            // For now, we will just output message without extra coloring, but we need to include magenta for "╰────"
            // Build: spaces, then "╰──── " in magenta, then message
            let mut colored_msg = String::new();
            // Add magenta for "╰" and dashes
            colored_msg.push_str(&format!("\x1b[35m╰\x1b[0m"));
            for _ in 0..4 {
                colored_msg.push_str(&format!("\x1b[35m─\x1b[0m"));
            }
            colored_msg.push_str(" ");
            // Color parts of message: if message contains "`inherit`" etc, color inside
            // We'll do simple replacement: find backtick segments
            let re_bt = Regex::new(r"`([^`]+)`").unwrap();
            let message_colored = re_bt.replace_all(&msg, |caps: &regex::Captures| {
                format!("\x1b[36m{}\x1b[0m", &caps[1])
            }).to_string();
            // Also color some keywords like "let in", "true", "false", "[]", etc with cyan? Original does for some.
            // We'll for simplicity just use message_colored

            out.push_str(&format!(" \x1b[38;5;246m  ·\x1b[0m{}{}{}\n", " ".repeat(diag.col + 4), colored_msg, message_colored));
        }
        out.push_str(&format!("\x1b[38;5;246m───╯\x1b[0m\n"));
    }

    out
}

// Diff generation for fix
fn generate_diff(path: &str, original: &str, fixed: &str) -> String {
    // If same, return "\n" per original behavior for fix --dry-run on valid file? Actually original returns "\n" (single newline) when no fix needed? Let's check: earlier fix --dry-run on valid file gave output "\n" (one empty line)
    if original == fixed {
        return "\n".to_string();
    }
    // Generate unified diff with one context? Original diff format:
    // --- <path>
    // +++ <path> [fixed]
    // @@ -1 +1 @@
    // -old
    // +new
    // For multiline, need more complex

    // Split into lines
    let orig_lines: Vec<&str> = original.lines().collect();
    let fixed_lines: Vec<&str> = fixed.lines().collect();

    // If both single line, produce simple diff
    if orig_lines.len() == 1 && fixed_lines.len() == 1 {
        let mut diff = String::new();
        diff.push_str(&format!("--- {}\n", path));
        diff.push_str(&format!("+++ {} [fixed]\n", path));
        diff.push_str("@@ -1 +1 @@\n");
        diff.push_str(&format!("-{}\n", orig_lines[0]));
        diff.push_str(&format!("+{}\n", fixed_lines[0]));
        diff.push_str("\n");
        return diff;
    }

    // For multi-line, we need to produce diff with context
    // Simplified: just show all lines changed? We'll produce generic unified diff
    // Use difflib? We have difflib crate? Actually we have diff crate 0.1.13, but we can implement simple.

    // For simplicity, we'll produce diff that lists all original lines as removed and fixed as added, with hunk header
    let mut diff = String::new();
    diff.push_str(&format!("--- {}\n", path));
    diff.push_str(&format!("+++ {} [fixed]\n", path));
    // Count lines
    diff.push_str(&format!("@@ -1,{} +1,{} @@\n", orig_lines.len(), fixed_lines.len()));
    for line in orig_lines {
        diff.push_str(&format!("-{}\n", line));
    }
    for line in fixed_lines {
        diff.push_str(&format!("+{}\n", line));
    }
    diff.push_str("\n");
    diff
}

fn apply_fixes(content: &str, diags: &[Diagnostic]) -> String {
    // Apply fixes in reverse order of offset to avoid shifting
    let mut fixes: Vec<(usize, usize, String)> = Vec::new();
    for d in diags {
        if let Some((s, e, repl)) = &d.fix_range {
            fixes.push((*s, *e, repl.clone()));
        }
    }
    // Sort by start descending
    fixes.sort_by(|a, b| b.0.cmp(&a.0));
    let mut result = content.to_string();
    for (s, e, repl) in fixes {
        if s <= result.len() && e <= result.len() && s <= e {
            result.replace_range(s..e, &repl);
        }
    }
    result
}

fn collect_nix_files(target: &str, unrestricted: bool, ignore_patterns: &[String]) -> Vec<PathBuf> {
    let path = Path::new(target);
    let mut files = Vec::new();
    if path.is_file() {
        if path.extension().and_then(|s| s.to_str()) == Some("nix") {
            files.push(path.to_path_buf());
        }
        return files;
    }
    // directory
    let mut builder = WalkBuilder::new(path);
    builder.hidden(false);
    builder.git_ignore(!unrestricted);
    builder.ignore(false);
    // Don't use git_exclude?
    // For ignore patterns, we will use override? Let's use WalkBuilder with override
    // Build override matcher from ignore_patterns
    // The ignore crate's OverrideBuilder can handle globs
    if !ignore_patterns.is_empty() {
        let mut override_builder = ignore::overrides::OverrideBuilder::new(path);
        for pat in ignore_patterns {
            // If pattern starts with "!"? Not needed
            // For exclusion, override with "!pattern" means include? Actually ignore crate override: if pattern matches, file is included. To ignore, we need to add "!pattern" ?
            // Simpler: we will manually filter after walk using glob crate matching basename or path
        }
    }

    for entry in builder.build() {
        if let Ok(entry) = entry {
            let p = entry.path();
            if p.is_file() {
                if p.extension().and_then(|s| s.to_str()) == Some("nix") {
                    // Check ignore patterns manually
                    let mut ignored = false;
                    let file_name = p.file_name().and_then(|s| s.to_str()).unwrap_or("");
                    let rel_path = p.strip_prefix(path).unwrap_or(p).to_string_lossy();
                    for pat_str in ignore_patterns {
                        // Try glob matching against file_name and rel_path and full path
                        if let Ok(pat) = Pattern::new(pat_str) {
                            if pat.matches(file_name) || pat.matches(&rel_path) || pat.matches(&p.to_string_lossy()) {
                                ignored = true;
                                break;
                            }
                            // Also try pattern with "**" handling: for "a.nix" we matched file_name, for "*.nix" matches file_name
                            // For ".direnv/*", we need to match rel_path starts with ".direnv/"
                            if pat_str.contains('*') {
                                // Already handled by Pattern
                            } else {
                                // If pattern is simple substring like ".direnv", check if rel_path contains it
                                if rel_path.contains(pat_str) {
                                    ignored = true;
                                    break;
                                }
                            }
                        } else {
                            // If pattern invalid, treat as substring
                            if rel_path.contains(pat_str) || file_name.contains(pat_str) {
                                ignored = true;
                                break;
                            }
                        }
                    }
                    if !ignored {
                        files.push(p.to_path_buf());
                    }
                }
            }
        }
    }
    files
}

