                std::process::exit(0);
            }
            let config = match load_config(&config_path) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("{}", e);
                    std::process::exit(0);
                }
            };
            let disabled_set: HashSet<String> = config.disabled.into_iter().collect();
            if stdin_mode {
                let mut buffer = String::new();
                io::stdin().read_to_string(&mut buffer).unwrap();
                let diags = lint_file("<stdin>", &buffer, &disabled_set);
                let mut found = None;
                for d in &diags {
                    if d.line == line && col >= d.col && col <= d.end_col {
