                        if *s <= fixed.len() && *e <= fixed.len() {
                            fixed.replace_range(*s..*e, repl);
                        }
                        if dry_run {
                            print!("{}", generate_diff("<stdin>", &buffer, &fixed));
                        } else {
                            print!("{}", fixed);
                        }
                    } else {
                        if dry_run {
                            print!("\n");
                        } else {
