                        }
                    }
                } else {
                    if dry_run {
                        print!("\n");
                    } else {
                        println!("single fix error: nothing to fix");
                    }
                }
            } else {
                let path = Path::new(&target);
                if !path.is_file() {
                    println!("single fix error: nothing to fix");
