                        break;
                    }
                }
                if let Some(diag) = found {
                    if let Some((s, e, repl)) = diag.fix_range {
                        let mut fixed = content.clone();
                        if s <= fixed.len() && e <= fixed.len() {
                            fixed.replace_range(s..e, &repl);
                        }
                        if dry_run {
