                            if pat.matches(file_name) || pat.matches(&rel_path) || pat.matches(&p.to_string_lossy().to_string()) {
                                ignored = true;
                                break;
                            }
                            if rel_path.contains(pat_str) {
                                ignored = true;
                                break;
                            }
                        } else {
                            if rel_path.contains(pat_str) || file_name.contains(pat_str) {
                                ignored = true;
                                break;
                            }
                        }
                    }
                    if !ignored {
                        files.push(p.to_path_buf());
                    }
                }
